        const tricky=[["Ag","NO3"],["NH4","PO4"],["Pb","Cl"],["Ba","SO4"],["K","S"],["Hg2","I"],["Ag","SO4"],["NH4","CO3"],["Ca","SO4"],["Rb","OH"]];
